insert into public.tasks(title,owner,stream,anchor,at_n,hard,note) values
('Agree your operating rhythm: 30-min weekly check-in and who owns which workstream','both','us','week',14,false,'See the playbook. One owner per task; ''Both'' only for genuine joint decisions.'),
('Flu vaccine','me','health','week',14,false,'Offered free at any stage of pregnancy during the autumn/winter season (GP, pharmacy or maternity unit).'),
('Get a maternity exemption certificate (MatEx)','me','health','week',15,false,'Free NHS prescriptions and dental care during pregnancy and for 12 months after. Ask your midwife for form FW8.'),
('Map the mixed care pathway: what is NHS, what is private, and the costs','both','health','week',15,false,'Private scans, consultant, birth location. Confirm who holds your notes and how private results reach the NHS team.'),
('Confirm 20-week anomaly scan date and book leave for both','me','health','week',16,false,'Scan is done between 18+0 and 20+6 weeks.'),
('Read both employers'' family-leave policies','both','work','week',16,false,'Enhanced maternity/paternity pay, clawback clauses, KIT days, return terms.'),
('Build the leave-period household budget','partner','work','week',16,false,'Statutory Maternity Pay: 6 weeks at 90% of average weekly earnings, then 33 weeks at £194.32 or 90% if lower (2026/27 rate). Add any employer top-up.'),
('Book antenatal classes (NHS free sessions plus any private course)','partner','birth','week',17,false,'Private courses for ~30–34 weeks fill early.'),
('Whooping cough vaccine','me','health','week',20,false,'Offered from 16 weeks; best given around the 20-week scan.'),
('Decide maternity leave start date and length','both','work','week',20,false,'Earliest start is 11 weeks before the expected week of childbirth.'),
('Shortlist, visit and join nursery waiting lists','partner','childcare','week',20,false,'London waiting lists can run a year or more.'),
('Collect MATB1 certificate and send it to HR','me','work','week',21,false,'Midwife or GP can issue it from 20 weeks.'),
('Tell your employer: pregnancy, due week and leave start date','me','work','week',22,true,'Legal deadline is the end of the 15th week before the expected week of childbirth (about week 25). Target week 22 for buffer.'),
('Give paternity leave notice to employer','partner','work','week',22,true,'Notice due 15 weeks before the expected week of childbirth. Leave is a day-one right; can be taken as two 1-week blocks within 52 weeks of birth. Paternity pay still needs 26 weeks'' service.'),
('Plan the baby''s sleep space for the first six months','both','home','week',22,false,'Safer-sleep guidance: baby sleeps in your room, on a firm flat mattress.'),
('Plan protected time together before the third trimester','both','us','week',22,false,'Airline cut-offs for travel in late pregnancy vary; check before booking.'),
('Big-kit decisions: pram, car seat, cot or Moses basket','both','home','week',24,false,'Decide buy, borrow or second-hand. Car seats: buy new or from a trusted source only.'),
('Check funded childcare and Tax-Free Childcare eligibility','partner','childcare','week',24,false,'Working-parent 30 hours runs from the term after baby turns 9 months; each parent must earn at least the minimum threshold and have adjusted net income of £100k or less.'),
('Wills, guardians and life insurance','partner','admin','week',24,false,'If unmarried, check parental responsibility rules for birth registration.'),
('24–28 week tests if offered (e.g. glucose tolerance test)','me','health','week',24,false,''),
('Work handover plan and cover discussion with manager','me','work','week',26,false,''),
('RSV vaccine','me','health','week',28,false,'Offered from 28 weeks; soonest after 28 weeks gives the baby most protection.'),
('28-week appointment and bloods','me','health','week',28,false,'Anti-D is offered if you are rhesus negative.'),
('Learn perinatal mental health warning signs, for both parents','both','us','week',30,false,'Agree now how either of you will raise concerns, and who to call (GP, midwife, health visitor).'),
('Tour the birth unit; plan route, parking and timing','partner','birth','week',32,false,''),
('Buy and fit car seat; practise installing it','partner','home','week',32,false,''),
('Postnatal support plan: helpers, visitor rules, meal rota','both','us','week',32,false,''),
('Infant feeding preparation','me','birth','week',32,false,'Class or session with a feeding specialist; decide what kit you need.'),
('Assemble cot or crib and buy a firm flat mattress','partner','home','week',33,false,''),
('Write birth preferences together and discuss with your midwife or obstetrician','both','birth','week',34,false,'Include pain relief, feeding, and what you''d want if plans change.'),
('Cook and freeze 10–15 meals','partner','home','week',34,false,''),
('Wash baby clothes and set up a changing station','partner','home','week',34,false,''),
('Paperwork folder: notes, MATB1 copy, insurance, ID for registration','partner','admin','week',34,false,''),
('Pack hospital bags (you, baby, partner)','both','birth','week',36,false,''),
('Labour logistics: who to call, when to go in, home cover','partner','birth','week',36,false,'Write key numbers on paper as well as phones.'),
('Last working day, out-of-office and KIT-day agreement','me','work','week',36,false,'Up to 10 keeping-in-touch days, by agreement.'),
('Confirm partner''s leave dates and handover','partner','work','week',36,false,''),
('Stock up: nappies, wipes, maternity pads, night lights','partner','home','week',37,false,''),
('Clear the calendar from week 38','both','us','week',38,false,''),
('Newborn blood spot (heel prick) test','both','health','birth',5,false,'Usually done by the midwife around day 5.'),
('Couple check-in: night shifts and task rebalance','both','us','birth',7,false,''),
('Health visitor new-birth visit','both','health','birth',12,false,'Usually 10–14 days after birth.'),
('Register baby with your GP','partner','admin','birth',14,false,''),
('Plan partner''s second paternity leave block, if taking one','partner','work','birth',14,false,''),
('Register the birth','partner','admin','birth',30,true,'Legal deadline in England: within 42 days. Target 30 days for buffer.'),
('Claim Child Benefit','partner','admin','birth',35,false,'Claims backdate up to 3 months. Claim even if you opt out of payments, so the child gets a National Insurance number.'),
('6–8 week postnatal check (you) and baby check','me','health','birth',42,false,''),
('Book 8-week vaccinations','partner','health','birth',50,false,'Given at 8, 12 and 16 weeks.'),
('Update wills and add baby to insurance, if not done','partner','admin','birth',60,false,''),
('Apply for your childcare funding code','partner','childcare','birth',161,false,'Apply up to 16 weeks before baby turns 9 months; deadline is the day before the term you want funding to start.'),
('Return-to-work plan and any flexible working request','me','work','birth',180,false,'Flexible working requests are a day-one right.');
